// Financial operation ledger, always merchant-scoped. Production dispatch is one
// typed River job per accepted operation; batch claims remain only for
// regression fixtures.
// Idempotent on (merchant_id, idempotency_key); returns the canonical row. On
// conflict a pending intent with attempts=0 refreshes its schedule and payload;
// a superseded or expired one revives with attempts reset; anything else is
// untouched. Frozen operations (tier changes, collections, manual rebills,
// sales, initial membership) are never refreshed or revived: a same-key race
// must not replace a frozen commercial decision.
func (q *Queries) EnqueueProviderIntent(ctx context.Context, arg EnqueueProviderIntentParams) (BillingProviderIntent, error) {
	row := q.db.QueryRow(ctx, enqueueProviderIntent,
		arg.ID,
		arg.MerchantID,
		arg.Rail,
		arg.IntentType,
		arg.SubscriptionID,
		arg.PaymentID,
		arg.PriceID,
		arg.Payload,
		arg.IdempotencyKey,
		arg.NextAttemptAt,
		arg.Origin,
		arg.OriginReason,
		arg.Actor,
		arg.Subject,
		arg.Credential,
		arg.ExpiresAt,
		arg.PspID,
		arg.CustodianID,
	)
	var i BillingProviderIntent
	err := row.Scan(
		&i.ID,
		&i.MerchantID,
		&i.Rail,
		&i.IntentType,
		&i.SubscriptionID,
		&i.PaymentID,
		&i.PriceID,
		&i.Payload,
		&i.IdempotencyKey,
		&i.Status,
		&i.Attempts,
		&i.NextAttemptAt,
		&i.LeaseExpiresAt,
		&i.Origin,
		&i.OriginReason,
		&i.Actor,
		&i.LastFailureReason,
		&i.ExpiresAt,
		&i.ResultEvidence,
		&i.CreatedAt,
		&i.ExecutedAt,
		&i.UpdatedAt,
		&i.PspID,
		&i.DestructiveRunID,
		&i.DestructiveRunClass,
		&i.CustodianID,
		&i.Subject,
		&i.Credential,
	)
	return i, err
}

const expireOverdueProviderIntents = `-- name: ExpireOverdueProviderIntents :execrows
UPDATE billing.provider_intents pi
SET status = 'expired',
    last_failure_reason = 'relevance window elapsed before execution',
    lease_expires_at = NULL,
    updated_at = now()
WHERE pi.merchant_id = $1::uuid AND (pi.status = 'failed_retryable' OR (pi.status = 'pending' AND pi.attempts = 0))
  AND NOT (pi.intent_type IN ('invoice_collection','subscription_collection') AND coalesce(pi.result_evidence, '{}'::jsonb) ? 'submitted_at')
  AND NOT (pi.intent_type = 'nmi_sale' AND coalesce(pi.result_evidence, '{}'::jsonb) ? 'sale_submitted')
  AND NOT (pi.intent_type='initial_membership' AND coalesce(pi.result_evidence,'{}'::jsonb) ? 'initial_submitted')
  AND pi.expires_at IS NOT NULL
  AND pi.expires_at <= $2::timestamptz
  AND NOT (
        pi.intent_type = ANY ($3::text[])
        AND EXISTS (
            SELECT 1 FROM billing.reconciliation_findings f
            WHERE f.merchant_id = $1::uuid AND f.merchant_id = pi.merchant_id
              AND f.finding_type = 'life.provider_intent.held_bulk'
              AND f.status IN ('reconcile_required', 'requires_review')
        )
      )
  AND pi.intent_type <> 'subscription_collection'
`

type ExpireOverdueProviderIntentsParams struct {
	MerchantID       uuid.UUID
	Now              time.Time
	BreakerHeldTypes []string
}

// Destructive intents held by the volume breaker (an open
// life.provider_intent.held_bulk finding) never expire while held: the
// operator's resolution decides.
func (q *Queries) ExpireOverdueProviderIntents(ctx context.Context, arg ExpireOverdueProviderIntentsParams) (int64, error) {
	result, err := q.db.Exec(ctx, expireOverdueProviderIntents, arg.MerchantID, arg.Now, arg.BreakerHeldTypes)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

