const markProviderIntentFailedRetryable = `-- name: MarkProviderIntentFailedRetryable :execrows
UPDATE billing.provider_intents
SET status = 'failed_retryable',
	result_evidence = result_evidence - 'recovery_held',
    next_attempt_at = $1::timestamptz,
    last_failure_reason = $2,
    lease_expires_at = NULL,
    updated_at = now()
WHERE provider_intents.merchant_id = $3::uuid AND id = $4 AND status IN ('in_flight', 'unknown_needs_verify')
  AND NOT (intent_type IN ('invoice_collection','subscription_collection') AND rail <> 'stripe' AND coalesce(result_evidence, '{}'::jsonb) ? 'submitted_at'
           AND NOT (intent_type = 'subscription_collection' AND coalesce(result_evidence, '{}'::jsonb) ? 'resend_armed'))
  AND NOT (intent_type = 'nmi_sale' AND rail <> 'stripe' AND coalesce(result_evidence, '{}'::jsonb) ? 'sale_submitted')
  AND NOT (intent_type = 'initial_membership' AND rail <> 'stripe' AND coalesce(result_evidence, '{}'::jsonb) ? 'initial_submitted')
`

type MarkProviderIntentFailedRetryableParams struct {
	NextAttemptAt time.Time
	Reason        *string
	MerchantID    uuid.UUID
	ID            uuid.UUID
}

func (q *Queries) MarkProviderIntentFailedRetryable(ctx context.Context, arg MarkProviderIntentFailedRetryableParams) (int64, error) {
	result, err := q.db.Exec(ctx, markProviderIntentFailedRetryable,
		arg.NextAttemptAt,
		arg.Reason,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const markProviderIntentFailedTerminal = `-- name: MarkProviderIntentFailedTerminal :execrows
UPDATE billing.provider_intents
SET status = 'failed_terminal',
    last_failure_reason = $1,
    result_evidence = CASE
        WHEN result_evidence ?| ARRAY['qualified_receipt', 'qualified_enrollment', 'account_requalifications']
        THEN COALESCE($2::jsonb, '{}'::jsonb)
          || CASE WHEN result_evidence ? 'qualified_receipt'
                  THEN jsonb_build_object('qualified_receipt', result_evidence->'qualified_receipt') ELSE '{}'::jsonb END
          || CASE WHEN result_evidence ? 'qualified_enrollment'
                  THEN jsonb_build_object('qualified_enrollment', result_evidence->'qualified_enrollment') ELSE '{}'::jsonb END
          || CASE WHEN result_evidence ? 'account_requalifications'
                  THEN jsonb_build_object('account_requalifications', result_evidence->'account_requalifications') ELSE '{}'::jsonb END
        ELSE $2::jsonb
    END,
    lease_expires_at = NULL,
    updated_at = now()
WHERE provider_intents.merchant_id = $3::uuid AND id = $4 AND status IN ('in_flight', 'unknown_needs_verify')
  AND intent_type NOT IN ('invoice_collection','manual_rebill','nmi_upgrade','stripe_tier_change','nmi_sale','initial_membership','nmi_vault_delete','hyperswitch_method_delete','subscription_collection')
`

type MarkProviderIntentFailedTerminalParams struct {
	Reason         *string
	ResultEvidence []byte
	MerchantID     uuid.UUID
	ID             uuid.UUID
}

func (q *Queries) MarkProviderIntentFailedTerminal(ctx context.Context, arg MarkProviderIntentFailedTerminalParams) (int64, error) {
	result, err := q.db.Exec(ctx, markProviderIntentFailedTerminal,
		arg.Reason,
		arg.ResultEvidence,
		arg.MerchantID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

