const renewProviderIntentClaim = `-- name: RenewProviderIntentClaim :execrows
UPDATE billing.provider_intents
SET lease_expires_at = $1::timestamptz,
    updated_at = now()
WHERE provider_intents.merchant_id = $2::uuid AND id = $3
  AND status = $4::text
  AND attempts = $5::int
  AND lease_expires_at IS NOT NULL
  AND lease_expires_at > $6::timestamptz
`

type RenewProviderIntentClaimParams struct {
	LeaseExpiresAt time.Time
	MerchantID     uuid.UUID
	ID             uuid.UUID
	Status         string
	Attempts       int32
	Now            time.Time
}

// Renews a live claim while its handler runs: the executor beats every lease/4,
// so lease_expires_at measures silence from a dead executor, not provider
// latency. A lapsed lease is never renewed (another executor may hold the row);
// only the claim's own (status, attempts) fencing token renews. 0 rows = lost.
func (q *Queries) RenewProviderIntentClaim(ctx context.Context, arg RenewProviderIntentClaimParams) (int64, error) {
	result, err := q.db.Exec(ctx, renewProviderIntentClaim,
		arg.LeaseExpiresAt,
		arg.MerchantID,
		arg.ID,
		arg.Status,
		arg.Attempts,
		arg.Now,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

